public class Demo {
    static int square(int x) {
        return x * x;
    }

    public static void main(String[] args) {
        long sum = 0;
        for (int i = 0; i < 1_000_000; i++) {
            sum += square(i % 100);
        }
        System.out.println(sum);
    }
}
